styles:
/* Aylık Sayım Sonucu — modern detay sayfası */
.ass-page {
  --ass-primary: #4557a3;
  --ass-primary-mid: #586495;
  --ass-accent: #5b6fd6;
  --ass-muted: #94a3b8;
  --ass-label: #64748b;
  --ass-text: #1e293b;
  --ass-border: #e2e8f0;
  --ass-surface: #ffffff;
  --ass-soft: #f8fafc;
  --ass-shadow: 0 4px 24px rgba(69, 87, 163, 0.08);
  --ass-radius: 16px;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 100%;
  min-height: 100%;
  margin: 0;
  padding: 1.25rem 1rem 2.5rem;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--ass-text);
  background: linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%);
  box-sizing: border-box;
}

@media (min-width: 768px) {
  .ass-page {
    padding: 1.5rem 1.5rem 2.75rem;
  }
}

@media (min-width: 1200px) {
  .ass-page {
    padding: 1.75rem 2rem 3rem;
  }
}

.ass-page *,
.ass-page *::before,
.ass-page *::after {
  box-sizing: border-box;
}

/* Toolbar */
.ass-page .ass__toolbar {
  order: -20;
  flex: 0 0 auto;
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 0 1rem 0 !important;
  padding: 0 !important;
}

.ass-page .ass__toolbar > .row,
.ass-page .ass__toolbar .row {
  display: flex !important;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
  width: 100% !important;
  margin: 0 !important;
}

.ass-page .ass__toolbar .col,
.ass-page .ass__toolbar [class*='col-'] {
  flex: 0 1 auto;
  width: auto !important;
  max-width: none;
  padding: 0 !important;
}

.ass-page .ass__toolbar .col:last-child,
.ass-page .ass__toolbar [class*='col-']:last-child {
  margin-left: auto;
}

.ass-page .ass__toolbar .p-button {
  border-radius: 10px;
  font-weight: 600;
  min-height: 2.5rem;
}

.ass-page .ass__toolbar .p-button-success,
.ass-page .ass__toolbar .p-button.p-button-success {
  box-shadow: 0 4px 14px rgba(34, 197, 94, 0.2);
}

/* Hero */
.ass-page .ass__hero {
  order: -10;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  margin-bottom: 1.25rem;
  padding: 1.35rem 1.5rem;
  border-radius: var(--ass-radius);
  background: linear-gradient(135deg, #4557a3 0%, #5b6fd6 55%, #7c8ce8 100%);
  color: #fff;
  box-shadow: 0 12px 40px rgba(69, 87, 163, 0.25);
}

.ass-page .ass__hero-main {
  flex: 1 1 240px;
  min-width: 0;
}

.ass-page .ass__eyebrow {
  display: block;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.85;
  margin-bottom: 0.35rem;
}

.ass-page .ass__hero h1 {
  margin: 0 0 0.4rem;
  font-size: clamp(1.2rem, 2.5vw, 1.55rem);
  font-weight: 800;
  line-height: 1.25;
}

.ass-page .ass__hero-sub {
  margin: 0;
  font-size: 0.92rem;
  opacity: 0.92;
  line-height: 1.5;
}

.ass-page .ass__hero-meta {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}

.ass-page .ass__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.28);
  color: #fff;
}

.ass-page .ass__chip i {
  font-size: 0.82rem;
  opacity: 0.9;
}

/* Liste kartı */
.ass-page .ass__list-card {
  width: 100%;
  margin-bottom: 1.25rem;
  background: var(--ass-surface);
  border: 1px solid var(--ass-border);
  border-radius: var(--ass-radius);
  box-shadow: var(--ass-shadow);
  overflow: hidden;
}

.ass-page .ass__list-card > .form-container,
.ass-page .ass__list-card .form-container {
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
}

.ass-page .ass__list-head {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 1.1rem 1.25rem;
  border-bottom: 1px solid var(--ass-border);
  background: linear-gradient(180deg, #f8fafc 0%, #fff 100%);
}

.ass-page .ass__list-head-icon {
  flex: 0 0 auto;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: #eef2ff;
  color: var(--ass-primary);
  font-size: 1rem;
}

.ass-page .ass__list-head h2 {
  margin: 0 0 0.15rem;
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--ass-text);
}

.ass-page .ass__list-head p {
  margin: 0;
  font-size: 0.82rem;
  color: var(--ass-label);
  line-height: 1.4;
}

/* Tablo */
.ass-page .ass__inventory {
  padding: 0;
}

.ass-page .ass-table-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.ass-page .ass-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}

.ass-page .ass-table thead {
  background: var(--ass-soft);
  border-bottom: 2px solid var(--ass-border);
}

.ass-page .ass-table th {
  padding: 0.85rem 1.15rem;
  text-align: left;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ass-label);
  white-space: nowrap;
}

.ass-page .ass-table th.ass-table__qty,
.ass-page .ass-table td.ass-table__qty {
  text-align: right;
  width: 7rem;
}

.ass-page .ass-table th.ass-table__num,
.ass-page .ass-table td.ass-table__num {
  width: 3.25rem;
  text-align: center;
  color: var(--ass-muted);
  font-weight: 700;
  font-size: 0.78rem;
}

.ass-page .ass-table tbody {
  counter-reset: ass-row;
}

.ass-page .ass-table tbody .ass-table__num::before {
  counter-increment: ass-row;
  content: counter(ass-row);
}

.ass-page .ass-table__row {
  border-bottom: 1px solid #f1f5f9;
  transition: background 0.12s ease;
}

.ass-page .ass-table__row:hover {
  background: #f8fafc;
}

.ass-page .ass-table__row:last-child {
  border-bottom: none;
}

.ass-page .ass-table td {
  padding: 0.9rem 1.15rem;
  vertical-align: middle;
}

.ass-page .ass-table__link {
  display: inline-flex;
  align-items: flex-start;
  gap: 0.55rem;
  max-width: 100%;
  text-decoration: none;
  color: var(--ass-primary);
  font-weight: 700;
  line-height: 1.45;
  transition: color 0.12s ease;
}

.ass-page .ass-table__link:hover {
  color: var(--ass-accent);
}

.ass-page .ass-table__link-icon {
  flex: 0 0 auto;
  width: 1.75rem;
  height: 1.75rem;
  margin-top: 0.05rem;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: #eef2ff;
  color: var(--ass-primary);
  font-size: 0.78rem;
}

.ass-page .ass-table__link-text {
  flex: 1 1 auto;
  min-width: 0;
  word-break: break-word;
}

.ass-page .ass-table__link-arrow {
  flex: 0 0 auto;
  margin-top: 0.2rem;
  font-size: 0.68rem;
  opacity: 0;
  transform: translateX(-2px);
  transition: opacity 0.12s ease, transform 0.12s ease;
}

.ass-page .ass-table__link:hover .ass-table__link-arrow {
  opacity: 0.7;
  transform: translateX(0);
}

.ass-page .ass-qty-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2.5rem;
  padding: 0.35rem 0.65rem;
  border-radius: 999px;
  background: #eef2ff;
  color: var(--ass-primary);
  font-size: 0.86rem;
  font-weight: 800;
  line-height: 1;
}

.ass-page .ass__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  padding: 3rem 1.5rem;
  text-align: center;
  color: var(--ass-muted);
}

.ass-page .ass__empty i {
  font-size: 2rem;
  opacity: 0.55;
}

.ass-page .ass__empty p {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ass-label);
}

/* Eski loop/grid kalıntılarını gizle */
.ass-page .ass__list-card .loop,
.ass-page .ass__list-card .grid.ass__legacy-row {
  display: none !important;
}

@media (max-width: 767px) {
  .ass-page .ass__hero {
    padding: 1.1rem 1.15rem;
  }

  .ass-page .ass-table thead {
    display: none;
  }

  .ass-page .ass-table,
  .ass-page .ass-table tbody,
  .ass-page .ass-table tr,
  .ass-page .ass-table td {
    display: block;
    width: 100%;
  }

  .ass-page .ass-table__row {
    padding: 0.85rem 1rem;
    border-bottom: 1px solid var(--ass-border);
  }

  .ass-page .ass-table__row:hover {
    background: #fff;
  }

  .ass-page .ass-table td {
    padding: 0.25rem 0;
    text-align: left !important;
    width: 100% !important;
  }

  .ass-page .ass-table td.ass-table__num {
    display: none;
  }

  .ass-page .ass-table td.ass-table__qty {
    margin-top: 0.35rem;
  }

  .ass-page .ass-table td::before {
    content: attr(data-label);
    display: block;
    font-size: 0.64rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--ass-muted);
    margin-bottom: 0.2rem;
  }

  .ass-page .ass-table td.ass-table__name::before {
    display: none;
  }
}

@media print {
  .ass-page {
    background: #fff;
    padding: 0;
  }

  .ass-page .ass__toolbar {
    display: none !important;
  }

  .ass-page .ass__hero {
    box-shadow: none;
    border-radius: 0;
    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;
  }

  .ass-page .ass__list-card {
    box-shadow: none;
    border: 1px solid #ddd;
  }

  .ass-page .ass-table__link {
    color: #000;
  }

  .ass-page .ass-table__link-arrow {
    display: none;
  }
}

/* Personel Detay — profil kartı */

.ass-page .ass__profile-card {
  position: relative;
  width: 100%;
  margin-bottom: 1.25rem;
  padding: 0;
  background: var(--ass-surface, #fff);
  border: 1px solid var(--ass-border, #e2e8f0);
  border-radius: var(--ass-radius, 16px);
  box-shadow: var(--ass-shadow, 0 4px 24px rgba(69, 87, 163, 0.08));
  overflow: hidden;
}

.ass-page .ass__profile-card::before {
  content: '';
  display: block;
  height: 4px;
  background: linear-gradient(90deg, #4557a3 0%, #5b6fd6 55%, #7c8ce8 100%);
}

.ass-page .ass__profile-product,
.ass-page .ass__profile-product.grid,
.ass-page .ass__profile-product.row {
  display: flex !important;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 1.15rem 1.5rem;
  margin: 0 !important;
  padding: 1.25rem 1.2rem 1.3rem !important;
}

.ass-page .ass__profile-product > .column,
.ass-page .ass__profile-product > .col,
.ass-page .ass__profile-product [class*='col-'] {
  flex: 1 1 240px;
  min-width: 0;
  max-width: 100%;
  padding: 0 !important;
  width: auto !important;
}

.ass-page .ass__profile-product > .ass__profile-media,
.ass-page .ass__profile-product > .column.ass__profile-media {
  flex: 0 0 auto;
  width: auto !important;
  max-width: none;
}

.ass-page .ass__profile-product > .ass__profile-main,
.ass-page .ass__profile-product > .column.ass__profile-main {
  flex: 1 1 280px;
}

.ass-page .ass__profile-img,
.ass-page .ass__profile-product img {
  display: block;
  width: 7.5rem !important;
  height: 7.5rem !important;
  max-width: 100%;
  object-fit: cover;
  border-radius: 18px;
  border: 3px solid #e8edf5;
  box-shadow: 0 10px 28px rgba(69, 87, 163, 0.16);
  background: #f1f5f9;
}

.ass-page .ass__profile-details,
.ass-page .ass__profile-details.grid,
.ass-page .ass__profile-details.row {
  display: flex !important;
  flex-direction: column;
  gap: 0;
  width: 100%;
  margin: 0 !important;
}

.ass-page .ass__profile-details > .column,
.ass-page .ass__profile-details > .col,
.ass-page .ass__profile-details [class*='col-'] {
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0;
  flex: none !important;
  padding: 0 !important;
}

.ass-page .ass__profile-name-row {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 0 0.65rem !important;
  min-height: auto !important;
  border-bottom: 1px solid #eef2f7 !important;
  margin-bottom: 0.15rem !important;
}

.ass-page .ass__profile-name,
.ass-page .ass__profile-name span,
.ass-page .ass__profile-name a,
.ass-page .ass__profile-name-row .label {
  display: block;
  margin: 0 !important;
  font-size: clamp(1.25rem, 2.5vw, 1.6rem) !important;
  font-weight: 800 !important;
  color: #1e293b !important;
  line-height: 1.25 !important;
  letter-spacing: -0.02em;
  text-transform: none !important;
}

.ass-page .ass__profile-stat {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  background: none;
  border: none;
  border-bottom: 1px solid #eef2f7;
  border-radius: 0;
  padding: 0.7rem 0 !important;
  min-height: auto;
}

.ass-page .ass__profile-stat:last-child {
  border-bottom: none;
  padding-bottom: 0 !important;
}

.ass-page .ass__profile-stat .label,
.ass-page .ass__profile-stat label {
  display: block;
  margin: 0;
  word-break: break-word;
}

.ass-page .ass__profile-stat > .label:first-of-type,
.ass-page .ass__profile-stat > label:first-of-type {
  margin-bottom: 0.1rem;
  color: #64748b !important;
  font-size: 0.72rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.03em;
  text-transform: none;
}

.ass-page .ass__profile-stat > .label:last-of-type,
.ass-page .ass__profile-stat > label:last-of-type,
.ass-page .ass__profile-stat > .label + .label,
.ass-page .ass__profile-stat > label + label {
  color: #1e293b !important;
  font-size: 0.92rem !important;
  font-weight: 600 !important;
  line-height: 1.4;
  text-transform: none !important;
  letter-spacing: normal;
}

.ass-page .ass__sections-card .content-header {
  border-radius: 10px !important;
  margin: 0.75rem 0 !important;
  font-weight: 700 !important;
}

@media (min-width: 768px) {
  .ass-page .ass__profile-product,
  .ass-page .ass__profile-product.grid,
  .ass-page .ass__profile-product.row {
    padding: 1.4rem 1.35rem 1.4rem !important;
    gap: 1.35rem 1.75rem;
  }

  .ass-page .ass__profile-img,
  .ass-page .ass__profile-product img {
    width: 8.25rem !important;
    height: 8.25rem !important;
  }
}

@media (max-width: 575px) {
  .ass-page .ass__profile-product,
  .ass-page .ass__profile-product.grid,
  .ass-page .ass__profile-product.row {
    flex-direction: column;
    align-items: center;
    text-align: center;
  }

  .ass-page .ass__profile-details,
  .ass-page .ass__profile-details.grid,
  .ass-page .ass__profile-details.row {
    text-align: left;
    width: 100%;
  }
}

@media print {
  .ass-page .ass__toolbar {
    display: none !important;
  }
}

/* Performans Değerlendirme Rapor Özeti */

.ass-page .pdro-hero .ass__hero-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  justify-content: flex-end;
  max-width: 100%;
}

.ass-page .pdro-hero .ass__chip {
  line-height: 1.35;
  white-space: normal;
  text-align: left;
}

.ass-page .pdro-chip-hint,
.ass-page .pdro-th-hint,
.ass-page .pdro-delta-hint {
  display: inline;
  color: inherit;
  font-size: 0.78em;
  font-weight: 500;
  opacity: 0.82;
}

.ass-page .pdro-chip--score {
  background: rgba(255, 255, 255, 0.18) !important;
  border-color: rgba(255, 255, 255, 0.35) !important;
  color: #fff !important;
}

.ass-page .pdro-chip--prev {
  background: rgba(255, 255, 255, 0.12) !important;
  border-color: rgba(255, 255, 255, 0.28) !important;
  color: #fff !important;
}

.ass-page .pdro-chip--delta {
  background: rgba(255, 255, 255, 0.22) !important;
  border-color: rgba(255, 255, 255, 0.4) !important;
  color: #fff !important;
  font-weight: 700 !important;
}

.ass-page .pdro-chip--delta .pdro-chip-hint {
  font-weight: 500;
}

.ass-page .pdro-summary-row--delta .label,
.ass-page .pdro-summary-row--delta span:not(label) {
  color: #4557a3 !important;
}

.ass-page .pdro-summary-row--delta .pdro-delta-hint {
  display: block;
  margin-top: 0.15rem;
  color: #64748b !important;
  font-size: 0.76rem !important;
  font-weight: 500 !important;
}

.ass-page .pdro-summary-row--prev span:not(label) {
  color: #475569 !important;
}

/* Mini tablolar */
.ass-page .pdro-trend,
.ass-page .pdro-reviewers {
  margin: 0.5rem 1.15rem 0.35rem;
  padding: 0.65rem 0.75rem;
  border: 1px solid #e8edf5;
  border-radius: 12px;
  background: #fafbfd;
}

.ass-page .pdro-reviewers {
  margin-bottom: 0.85rem;
}

.ass-page .pdro-trend__title {
  margin: 0 0 0.65rem;
  color: #475569;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  text-transform: none;
}

.ass-page .pdro-trend__table-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.ass-page .pdro-trend__table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 0.86rem;
  line-height: 1.45;
}

.ass-page .pdro-trend__table thead th {
  padding: 0.55rem 0.65rem;
  text-align: left;
  vertical-align: bottom;
  background: #eef2ff;
  color: #4557a3;
  font-size: 0.76rem;
  font-weight: 700;
  border-bottom: 1px solid #dbeafe;
}

.ass-page .pdro-trend__table thead th.pdro-trend__num {
  text-align: right;
  white-space: nowrap;
}

.ass-page .pdro-th-main {
  display: block;
  line-height: 1.2;
}

.ass-page .pdro-th-hint {
  display: block;
  margin-top: 0.12rem;
  color: #64748b;
  font-size: 0.68rem;
  font-weight: 500;
  line-height: 1.2;
  text-transform: none;
  letter-spacing: 0;
}

.ass-page .pdro-summary-card--alt .pdro-trend__table thead th {
  background: #ecfdf5;
  color: #0f766e;
  border-bottom-color: #ccfbf1;
}

.ass-page .pdro-summary-card--alt .pdro-th-hint {
  color: #5f8f87;
}

.ass-page .pdro-trend__table tbody td {
  padding: 0.58rem 0.65rem;
  border-bottom: 1px solid #eef2f7;
  color: #1e293b;
  font-weight: 600;
  vertical-align: middle;
}

.ass-page .pdro-trend__table tbody td.pdro-trend__num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.ass-page .pdro-trend__table tbody tr:nth-child(even) td {
  background: #f8fafc;
}

.ass-page .pdro-trend__row--current td {
  background: #eef2ff !important;
  color: #4557a3 !important;
}

.ass-page .pdro-summary-card--alt .pdro-trend__row--current td {
  background: #ecfdf5 !important;
  color: #0f766e !important;
}

.ass-page .pdro-trend__table tbody tr:last-child td {
  border-bottom: none;
}

.ass-page .pdro-reviewers__table tfoot td {
  padding: 0.58rem 0.65rem;
  background: #eef2ff;
  color: #4557a3;
  font-weight: 800;
  border-top: 1px solid #dbeafe;
}

.ass-page .pdro-summary-card--alt .pdro-reviewers__table tfoot td {
  background: #ecfdf5;
  color: #0f766e;
  border-top-color: #ccfbf1;
}

/* Soru grubu özeti (A–E) */
.ass-page .pdro-question-groups {
  margin: 0.5rem 1.15rem 0.85rem;
  padding: 0.65rem 0.75rem;
  border: 1px solid #e8edf5;
  border-radius: 12px;
  background: #fafbfd;
}

.ass-page .pdro-question-group {
  margin-top: 0.75rem;
  padding: 0.7rem 0.75rem;
  border: 1px solid #e8edf5;
  border-radius: 10px;
  background: #fff;
}

.ass-page .pdro-question-group:first-of-type {
  margin-top: 0.35rem;
}

.ass-page .pdro-question-group--A { border-left: 4px solid #f4d58d; }
.ass-page .pdro-question-group--B { border-left: 4px solid #efb08f; }
.ass-page .pdro-question-group--C { border-left: 4px solid #9db7e5; }
.ass-page .pdro-question-group--D { border-left: 4px solid #d98ad9; }
.ass-page .pdro-question-group--E { border-left: 4px solid #a8d5a2; }

.ass-page .pdro-question-group__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.45rem 0.75rem;
  margin-bottom: 0.65rem;
}

.ass-page .pdro-question-group__badge {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.55rem;
  border-radius: 999px;
  background: #eef2ff;
  color: #4557a3;
  font-size: 0.76rem;
  font-weight: 800;
}

.ass-page .pdro-question-group__meta {
  color: #64748b;
  font-size: 0.8rem;
  font-weight: 600;
}

.ass-page .pdro-question-group__meta strong {
  color: #1e293b;
}

.ass-page .pdro-question-group__extremes {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.55rem;
  margin-bottom: 0.65rem;
}

@media (min-width: 720px) {
  .ass-page .pdro-question-group__extremes {
    grid-template-columns: 1fr 1fr;
  }
}

.ass-page .pdro-question-group__extreme {
  padding: 0.55rem 0.65rem;
  border-radius: 8px;
  background: #f8fafc;
  border: 1px solid #eef2f7;
}

.ass-page .pdro-question-group__extreme--low {
  border-color: #fecaca;
  background: #fff7f7;
}

.ass-page .pdro-question-group__extreme--high {
  border-color: #bbf7d0;
  background: #f4fdf7;
}

.ass-page .pdro-question-group__label {
  display: block;
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.ass-page .pdro-question-group__score {
  display: inline-block;
  margin: 0.15rem 0 0.35rem;
  color: #1e293b;
  font-size: 1rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.ass-page .pdro-question-group__criterion {
  margin: 0;
  color: #334155;
  font-size: 0.8rem;
  line-height: 1.45;
  font-weight: 500;
}

.ass-page .pdro-question-group__table-wrap {
  overflow-x: auto;
}

.ass-page .pdro-question-group__table td:first-child + td {
  min-width: 12rem;
}

.ass-page .pdro-chip--senior,
.ass-page .pdro-chip--junior,
.ass-page .pdro-chip--same {
  background: rgba(255, 255, 255, 0.14) !important;
  border-color: rgba(255, 255, 255, 0.28) !important;
  color: #fff !important;
}

/* Özet kartları */
.ass-page .pdro-summary-card {
  width: 100%;
  margin-bottom: 1.25rem;
  padding: 0;
  background: var(--ass-surface, #fff);
  border: 1px solid var(--ass-border, #e2e8f0);
  border-radius: var(--ass-radius, 16px);
  box-shadow: var(--ass-shadow, 0 4px 24px rgba(69, 87, 163, 0.08));
  overflow: hidden;
}

.ass-page .pdro-summary-card::before {
  content: '';
  display: block;
  height: 4px;
  background: linear-gradient(90deg, #4557a3 0%, #5b6fd6 55%, #7c8ce8 100%);
}

.ass-page .pdro-summary-card--alt::before {
  background: linear-gradient(90deg, #0d9488 0%, #14b8a6 55%, #5eead4 100%);
}

.ass-page .pdro-section-head-grid,
.ass-page .pdro-section-head-grid.grid,
.ass-page .pdro-section-head-grid.row {
  margin: 0 !important;
  padding: 1rem 1.15rem 0.35rem !important;
  background: transparent !important;
  border: none !important;
}

.ass-page .pdro-section-head-grid > .column,
.ass-page .pdro-section-head-grid > .col,
.ass-page .pdro-section-head-grid [class*='col-'] {
  padding: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
}

.ass-page .pdro-section-title,
.ass-page .pdro-section-title.label {
  display: block;
  margin: 0 !important;
  padding: 0 0 0.55rem !important;
  border-bottom: 2px solid #eef2ff;
  color: #4557a3 !important;
  font-size: 0.95rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.01em;
  text-transform: none !important;
  line-height: 1.4 !important;
}

.ass-page .pdro-summary-card--alt .pdro-section-title,
.ass-page .pdro-summary-card--alt .pdro-section-title.label {
  border-bottom-color: #ccfbf1;
  color: #0f766e !important;
}

.ass-page .pdro-summary-form,
.ass-page .pdro-summary-card .form-container {
  padding: 0.35rem 1.15rem 1.2rem !important;
  margin: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
}

.ass-page .pdro-summary-row,
.ass-page .pdro-summary-form .pdro-summary-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.22rem;
  margin: 0 !important;
  padding: 0.78rem 0 !important;
  border-bottom: 1px solid #eef2f7;
}

@media (min-width: 640px) {
  .ass-page .pdro-summary-row:not(.pdro-summary-action),
  .ass-page .pdro-summary-form .pdro-summary-row:not(.pdro-summary-action) {
    grid-template-columns: minmax(10rem, 42%) minmax(0, 1fr);
    align-items: start;
    column-gap: 1rem;
  }

  .ass-page .pdro-summary-row label,
  .ass-page .pdro-summary-form label {
    padding-top: 0.05rem;
  }
}

.ass-page .pdro-summary-row:last-child,
.ass-page .pdro-summary-form .pdro-summary-row:last-child {
  border-bottom: none;
}

.ass-page .pdro-summary-row .form-group,
.ass-page .pdro-summary-row .field,
.ass-page .pdro-summary-row .p-field {
  margin: 0 !important;
}

.ass-page .pdro-summary-row label,
.ass-page .pdro-summary-form label {
  display: block;
  margin: 0 !important;
  color: #64748b !important;
  font-size: 0.76rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.02em;
  line-height: 1.35;
}

.ass-page .pdro-summary-row .label,
.ass-page .pdro-summary-row span:not(label) {
  display: block;
  color: #1e293b !important;
  font-size: 0.94rem !important;
  font-weight: 600 !important;
  line-height: 1.45;
}

.ass-page .pdro-summary-action .label a,
.ass-page .pdro-summary-action a {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.15rem;
  padding: 0.38rem 0.8rem;
  border-radius: 999px;
  background: #eef2ff;
  border: 1px solid #c7d2fe;
  color: #4557a3 !important;
  font-size: 0.8rem !important;
  font-weight: 700 !important;
  text-decoration: none !important;
  transition: background 0.15s ease, transform 0.15s ease;
}

.ass-page .pdro-summary-action .label a:hover,
.ass-page .pdro-summary-action a:hover {
  background: #e0e7ff;
  transform: translateY(-1px);
}

/* Toolbar — PDF butonları */
.ass-page .ass__toolbar .p-button,
.ass-page .ass__toolbar button {
  border-radius: 999px !important;
  font-weight: 700 !important;
}

.ass-page .ass__toolbar .p-button-secondary,
.ass-page .ass__toolbar .p-button.p-button-secondary {
  background: #fff !important;
  border: 1px solid #c7d2fe !important;
  color: #4557a3 !important;
}

.ass-page .ass__toolbar .p-button-success,
.ass-page .ass__toolbar .p-button.p-button-success {
  background: linear-gradient(135deg, #4557a3, #5b6fd6) !important;
  border: none !important;
  color: #fff !important;
}

@media (max-width: 767px) {
  .ass-page .pdro-hero.ass__hero--person {
    flex-direction: column;
    align-items: flex-start;
  }

  .ass-page .pdro-hero .ass__hero-meta {
    justify-content: flex-start;
    width: 100%;
  }

  .ass-page .pdro-trend,
  .ass-page .pdro-reviewers {
    margin-left: 0.85rem;
    margin-right: 0.85rem;
    padding: 0.55rem 0.6rem;
  }
}
